<?php
namespace Tests\Feature;
use App\Enums\ApprovalStatus;use App\Enums\ApprovalType;use App\Enums\UserRole;use App\Models\ApprovalRequest;use App\Models\Category;use App\Models\Product;use App\Models\User;use Illuminate\Foundation\Testing\RefreshDatabase;use Laravel\Sanctum\Sanctum;use Tests\TestCase;
class NextStaffProductsApiTest extends TestCase{use RefreshDatabase;
public function test_owner_can_list_create_update_and_request_approved_changes():void{$owner=User::factory()->create(['role'=>UserRole::Owner]);$category=Category::create(['name'=>'ATK','slug'=>'atk','is_active'=>true]);Sanctum::actingAs($owner,['staff:products']);$created=$this->postJson('/api/v1/staff/products',['category_id'=>$category->id,'name'=>'Pulpen Next','sku'=>'PEN-NEXT','unit'=>'pcs','cost_price'=>2000,'selling_price'=>3000,'minimum_stock'=>5,'is_active'=>true])->assertCreated()->assertJsonPath('data.sku','PEN-NEXT');$product=Product::findOrFail($created->json('data.id'));$this->getJson('/api/v1/staff/products?q=PEN-NEXT')->assertOk()->assertJsonPath('data.products.0.name','Pulpen Next');$this->putJson('/api/v1/staff/products/'.$product->id,['category_id'=>$category->id,'name'=>'Pulpen Next Edit','sku'=>'PEN-NEXT','unit'=>'pcs','cost_price'=>2000,'selling_price'=>3000,'minimum_stock'=>6,'is_active'=>true])->assertOk();$this->assertSame('Pulpen Next Edit',$product->fresh()->name);$this->putJson('/api/v1/staff/products/'.$product->id,['category_id'=>$category->id,'name'=>'Pulpen Next Edit','sku'=>'PEN-NEXT','unit'=>'pcs','cost_price'=>2200,'selling_price'=>3500,'minimum_stock'=>6,'is_active'=>true])->assertStatus(202);$this->assertSame(3000,$product->fresh()->selling_price);$this->assertDatabaseHas('approval_requests',['type'=>ApprovalType::ProductPriceChange->value,'status'=>ApprovalStatus::Pending->value,'subject_id'=>$product->id]);}
public function test_stock_request_creates_approval_without_changing_stock():void{$admin=User::factory()->create(['role'=>UserRole::Admin]);$category=Category::create(['name'=>'Kertas','slug'=>'kertas','is_active'=>true]);$product=Product::create(['category_id'=>$category->id,'name'=>'Kertas A4','slug'=>'kertas-a4','sku'=>'A4-NEXT','unit'=>'rim','cost_price'=>50000,'selling_price'=>60000,'stock'=>3,'minimum_stock'=>2,'is_active'=>true]);Sanctum::actingAs($admin,['staff:products']);$this->postJson('/api/v1/staff/products/'.$product->id.'/stock',['quantity'=>10,'type'=>'purchase','reason'=>'Pembelian stok baru'])->assertStatus(202);$this->assertSame(3,$product->fresh()->stock);$this->assertDatabaseHas('approval_requests',['type'=>ApprovalType::StockAdjustment->value,'status'=>ApprovalStatus::Pending->value,'subject_id'=>$product->id]);}
public function test_unauthorized_roles_and_tokens_are_rejected():void{$category=Category::create(['name'=>'Uji','slug'=>'uji-produk','is_active'=>true]);$product=Product::create(['category_id'=>$category->id,'name'=>'Uji','slug'=>'uji','sku'=>'UJI','unit'=>'pcs','cost_price'=>1,'selling_price'=>2,'minimum_stock'=>0,'is_active'=>true]);$cashier=User::factory()->create(['role'=>UserRole::Cashier]);Sanctum::actingAs($cashier,['staff:products']);$this->getJson('/api/v1/staff/products')->assertForbidden();$owner=User::factory()->create(['role'=>UserRole::Owner]);Sanctum::actingAs($owner,['staff:dashboard']);$this->postJson('/api/v1/staff/products/'.$product->id.'/stock',['quantity'=>1,'type'=>'purchase','reason'=>'Tidak boleh'])->assertForbidden();}
}